def best_subset(profits, risks, limit):
    n = len(profits)
    best = 0
    for mask in range(1 << n):
        profit = risk = 0
        for i in range(n):
            if mask >> i & 1:
                profit += profits[i]
                risk += risks[i]
        if risk <= limit and profit > best:
            best = profit
    return best

def popcounts(n):
    p = [0] * (1 << n)
    for m in range(1, 1 << n):
        p[m] = p[m >> 1] + (m & 1)
    return p
